package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectionType_construct_TriageGen2Test {

    @Test
    public void testConstruct_withListAndInteger() {
        // Arrange
        Class<?> rawType = List.class;
        JavaType elemT = TypeFactory.defaultInstance().constructType(Integer.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Assert
        assertNotNull("Result should not be null", result);
        assertEquals("Raw type should match", rawType, result.getRawClass());
        assertEquals("Element type should match", elemT, result.getContentType());

        // Verify the internal structure via toString or public API if available
        // Since we are testing the specific construct method implementation provided:
        // It calls _bogusSuperClass(rawType) and sets specific fields.
        String toStringResult = result.toString();
        assertTrue(toStringResult.contains("java.util.List"));
        assertTrue(toStringResult.contains("java.lang.Integer"));
    }








}

