package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectionType_construct_TriageGen2Test {





    @Test
    public void testConstruct_withComplexType() {
        // Arrange
        // Creating a nested type: List<List<String>>
        TypeFactory tf = TypeFactory.defaultInstance();
        JavaType innerType = tf.constructType(String.class);
        JavaType outerElemType = tf.constructCollectionType(List.class, innerType);
        Class<?> rawType = List.class;

        // Act
        CollectionType result = CollectionType.construct(rawType, outerElemType);

        // Assert
        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(outerElemType, result.getContentType());
    }




}

